  const [bulkDomain, setBulkDomain] = useState("keep"), [bulkTier, setBulkTier] = useState("keep"), [deleting, setDeleting] = useState(false), [replacement, setReplacement] = useState("");
  const [classificationDirty, setClassificationDirty] = useState(false), [themeDirty, setThemeDirty] = useState(false);
  useEffect(() => { onDirtyChange?.(classificationDirty || themeDirty); }, [classificationDirty, themeDirty, onDirtyChange]);
  useEffect(() => () => onDirtyChange?.(false), [onDirtyChange]);
  useEffect(() => () => onDirtyChange?.(false), [onDirtyChange]);
  useEffect(() => { if (model) setSelected(previous => previous.every(id => model.tokens.some(token => token.id === id)) ? previous : previous.filter(id => model.tokens.some(token => token.id === id))); }, [model]);
  if (!model || !project) return null;
