  const names = new Map([...model.domains, ...model.tiers].map(item => [item.id, item.name]));
  const tokens = model.tokens.filter(token => unassigned(token.domain) === domain && unassigned(token.tier) === tier && (!aliases || activeTokenReferences(model, token).length > 0)
    && [token.name, token.id, token.description ?? "", token.typeRef.id, names.get(token.domain ?? "") ?? "", names.get(token.tier ?? "") ?? ""].join(" ").toLocaleLowerCase(locale).includes(query.trim().toLocaleLowerCase(locale)))
    .sort((a, b) => (sort === "uses" ? a.references.length - b.references.length : (sort === "type" ? a.typeRef.id : a.name).localeCompare(sort === "type" ? b.typeRef.id : b.name, locale, { numeric: true })) * (descending ? -1 : 1) || a.id.localeCompare(b.id));
  const graphTokens = tokens.some(token => activeTokenReferences(model, token).length > 0) ? tokens : model.tokens.filter(token => activeTokenReferences(model, token).some(reference => tokens.some(source => source.id === reference.ref.id)));
  const chosen = model.tokens.filter(token => selected.includes(token.id)), visibleSelected = tokens.filter(token => selected.includes(token.id));
